    <div class="rounded-xl border border-indigo-100 bg-indigo-50 p-5"><h3 class="font-bold">Chọn dạng in</h3><p class="mt-1 text-sm text-slate-600">Bản in có chữ ký sẽ được lưu cùng phiếu ngay trong lần in này.</p><div class="mt-4 grid gap-4 md:grid-cols-2"><label class="text-sm font-semibold">Tải ảnh chữ ký<input id="proposal-sign-file" type="file" accept="image/png,image/jpeg" class="mt-1 block w-full rounded border bg-white p-2"><span class="text-xs font-normal text-slate-500">Ảnh sẽ được làm trong nền sáng và lấy phần nét chữ ký.</span></label><div><label class="text-sm font-semibold">Ký trực tiếp trên web</label><canvas id="proposal-sign-canvas" width="520" height="170" class="mt-1 w-full touch-none rounded border bg-white"></canvas><button type="button" id="proposal-sign-clear" class="mt-2 rounded border px-3 py-1 text-sm">Xóa chữ ký</button></div></div><div class="mt-4 flex flex-wrap gap-2"><button type="button" id="proposal-print-unsigned" class="rounded bg-slate-700 px-4 py-2 font-semibold text-white">In chưa ký</button><button type="button" id="proposal-print-image" disabled class="rounded bg-blue-600 px-4 py-2 font-semibold text-white">In ký ảnh</button><button type="button" id="proposal-print-direct" disabled class="rounded bg-emerald-600 px-4 py-2 font-semibold text-white">In ký trực tiếp</button></div><p id="proposal-sign-status" class="mt-2 text-sm text-slate-600">Chưa có chữ ký.</p></div>
</div>
<script>
(()=>{const canvas=document.getElementById('proposal-sign-canvas'),file=document.getElementById('proposal-sign-file'),clear=document.getElementById('proposal-sign-clear'),status=document.getElementById('proposal-sign-status');if(!canvas)return;const ctx=canvas.getContext('2d');let data='',method='';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#111827';let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);method='draw'});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()});canvas.addEventListener('pointerup',()=>{drawing=false;data=canvas.toDataURL('image/png');method='draw';status.textContent='Đã tạo chữ ký trực tiếp.';buttons()});clear.onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);data='';method='';status.textContent='Chưa có chữ ký.';buttons()};file.onchange=()=>{const f=file.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{canvas.width=520;canvas.height=Math.max(120,Math.min(260,Math.round(520*img.height/img.width)));ctx.drawImage(img,0,0,canvas.width,canvas.height);const p=ctx.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<p.data.length;i+=4){const light=Math.min(p.data[i],p.data[i+1],p.data[i+2]);if(p.data[i]>225&&p.data[i+1]>225&&p.data[i+2]>225)p.data[i+3]=0;else if(light>170)p.data[i+3]=Math.max(0,255-Math.round((light-170)*3))}ctx.putImageData(p,0,0);data=canvas.toDataURL('image/png');method='upload';status.textContent='Đã làm nét và xóa nền sáng của ảnh chữ ký.';buttons()};img.src=reader.result};reader.readAsDataURL(f)};const buttons=()=>{document.getElementById('proposal-print-image').disabled=!(data&&method==='upload');document.getElementById('proposal-print-direct').disabled=!(data&&method==='draw')};const print=async mode=>{const token=document.querySelector('meta[name="csrf-token"]')?.content||'';const res=await fetch('{{ route('inventory.proposals.print',$proposal) }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'text/html'},body:JSON.stringify({print_mode:mode,signature_data:mode==='unsigned'?'':data})});document.open();document.write(await res.text());document.close()};document.getElementById('proposal-print-unsigned').onclick=()=>print('unsigned');document.getElementById('proposal-print-image').onclick=()=>print('image');document.getElementById('proposal-print-direct').onclick=()=>print('direct')})();
</script>
